import { ListTable, Panel, RowHeader } from './ui'
import { SplitLayout } from './SplitLayout'
// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Spec #1 review fixes"
// Changes: In a draft the G = (N, T, P, S) panel has the shared Changes toggle; while it is on, the panel shows the
